# ---- (C) S-2.10.8 pluggable image embedder (media/image_embed.py) ----
from impact_crater.llm_clients.base import Embedding  # numpy ndarray alias

class ImageEmbedder(Protocol):
    backend: str
    async def embed_image(self, image_bytes: bytes, *, content_hash: str) -> Embedding | None: ...

class RouterImageEmbedder:                 # default — today's behaviour
    backend = "router"
    def __init__(self, router: object) -> None: self._router = router
    async def embed_image(self, image_bytes, *, content_hash):
        return await self._router.embed_image(image_bytes, content_hash=content_hash)

class LocalClipImageEmbedder:              # STUB — weights/GPU, off by default
    backend = "local_clip"
    def __init__(self) -> None: self._model = None
    async def embed_image(self, image_bytes, *, content_hash):
        # lazy import open_clip / siglip; if unavailable or weights absent → None
        # (caller falls back to the router op). NO weights pulled at import time.
        return None  # until a real model is present

def build_image_embedder(backend: str | None, router: object) -> ImageEmbedder:
    chosen = (backend or "router").strip().lower()
    if chosen == "local_clip":
        return LocalClipImageEmbedder()
    return RouterImageEmbedder(router)

# stage2 fallback helper
async def _embed_with_fallback(embedder, router, image_bytes, content_hash):
    if embedder is not None:
        v = await embedder.embed_image(image_bytes, content_hash=content_hash)
        if v is not None:
            return v
    return await router.embed_image(image_bytes, content_hash=content_hash)
